documentation.usage:
Dialog { open: open(), on_open_change: move |v| open.set(v),
    DialogTrigger { "Open dialog" }
    DialogOverlay {}
    DialogContent {
        DialogHeader { DialogTitle { "Title" } DialogDescription { "Description" } }
        DialogFooter { DialogClose { "Close" } }
    }
}

Select::<String> {
    SelectTrigger { aria_label: "Choose a fruit", SelectValue { placeholder: "Choose a fruit" } }
    SelectList { aria_label: "Fruit options",
        SelectOption::<String> { index: 0usize, value: "apple".to_string(), text_value: "Apple".to_string(), "Apple" }
    }
}

Card {
    CardHeader { CardTitle { "Title" } CardDescription { "Description" } }
    CardContent { "Body content" }
    CardFooter { "Footer" }
}

ItemGroup {
    Item { variant: ItemVariant::Interactive, ItemContent { "Row label" } }
}

Pagination {
    PaginationContent {
        PaginationItem { PaginationPrevious {} }
        PaginationItem { PaginationLink { is_active: true, "1" } }
        PaginationItem { PaginationNext {} }
    }
}

Sheet { open: open(), on_open_change: move |v| open.set(v),
    SheetTrigger { "Open sheet" }
    SheetOverlay {}
    SheetContent {
        SheetHeader { SheetTitle { "Title" } }
        SheetFooter { SheetClose { "Close" } }
    }
}

Tooltip { open: open(), on_open_change: move |v| open.set(v),
    TooltipTrigger { "Hover me" }
    TooltipContent { "Helpful text" }
}

Popover { open: open(), on_open_change: move |v| open.set(v),
    PopoverTrigger { "Open popover" }
    PopoverContent { "Popover content" }
}

HoverCard { open: open(), on_open_change: move |v| open.set(v),
    HoverCardTrigger { "@username" }
    HoverCardContent { "Profile preview" }
}

DropdownMenu {
    DropdownMenuTrigger { "Open menu" }
    DropdownMenuContent {
        DropdownMenuItem { index: 0usize, value: "edit".to_string(), on_select: move |_| {}, "Edit" }
    }
}

ContextMenu {
    ContextMenuTrigger { "Right click here" }
    ContextMenuContent {
        ContextMenuItem { index: 0usize, value: "edit".to_string(), on_select: move |_| {}, "Edit" }
    }
}

Menubar {
    MenubarMenu { index: 0usize,
        MenubarTrigger { "File" }
        MenubarContent {
            MenubarItem { index: 0usize, value: "new".to_string(), on_select: move |_| {}, "New" }
        }
    }
}

Combobox::<String> {
    ComboboxInput { placeholder: "Search..." }
    ComboboxList {
        ComboboxOption::<String> { value: "a".to_string(), index: 0usize, "Option A" }
    }
}

DatePicker { value: value(), on_value_change: move |v| value.set(v),
    DatePickerInput {}
    DatePickerPopover { DatePickerCalendar {} }
}

SidebarProvider {
    Sidebar {
        SidebarHeader { "Logo" }
        SidebarContent { SidebarMenu { SidebarMenuItem { SidebarMenuButton { "Home" } } } }
    }
}

AspectRatio { ratio: 16.0 / 9.0,
    img { src: "image.png", alt: "Description" }
}

Progress { value: Some(60.0),
    ProgressIndicator {}
}

Avatar {
    AvatarImage { src: "user.png", alt: "Jane Doe" }
    AvatarFallback { "JD" }
}

Collapsible { open: open(), on_open_change: move |v| open.set(v),
    CollapsibleTrigger { "Toggle" }
    CollapsibleContent { "Content" }
}

Accordion { value: value(), on_value_change: move |v| value.set(v),
    AccordionItem { value: "item-1",
        AccordionTrigger { "Section title" }
        AccordionContent { "Section content" }
    }
}

RadioGroup { value: value(), on_value_change: move |v| value.set(v),
    RadioItem { value: "a", "Option A" }
    RadioItem { value: "b", "Option B" }
}

Tabs { value: value(), on_value_change: move |v| value.set(v),
    TabList {
        TabTrigger { value: "one", "Tab 1" }
    }
    TabContent { value: "one", "Panel 1" }
}

ToggleGroup { pressed: pressed(), on_pressed_change: move |v| pressed.set(v),
    ToggleItem { index: 0usize, "Bold" }
}

ScrollArea { style: "height: 12em;",
    div { "Long scrollable content..." }
}

AlertDialog { open: open(), on_open_change: move |v| open.set(v),
    AlertDialogTrigger { "Delete item" }
    AlertDialogContent {
        AlertDialogTitle { "Are you sure?" }
        AlertDialogDescription { "This cannot be undone." }
        AlertDialogActions {
            AlertDialogCancel { "Cancel" }
            AlertDialogAction { "Delete" }
        }
    }
}

ToastProvider {
    // elsewhere: use_toast().show(ToastType::Success, "Saved")
}

Slider { label: "Volume", default_value: 50.0,
    SliderTrack { SliderRange {} SliderThumb {} }
}

Toolbar { aria_label: "Text formatting",
    ToolbarButton { index: 0usize, on_click: move |_| {}, "Bold" }
    ToolbarSeparator {}
    ToolbarButton { index: 1usize, on_click: move |_| {}, "Italic" }
}

VirtualList {
    count: 1000usize,
    estimate_size: |_idx| 32,
    render_item: move |idx: usize| rsx! { div { "Row {idx}" } },
}

ColorPicker { color: color(), on_color_change: move |c| color.set(c),
    ColorArea { AreaTrack { AreaThumb { AreaThumbSaturationInput {} AreaThumbValueInput {} } } }
    HueSlider {}
}

DragAndDropList { items: items(), on_reorder: move |reordered| items.set(reordered),
    for item in items() {
        DragAndDropListItem { key: "{item}", "{item}" }
    }
}

TagGroup { values: values(), on_values_change: move |v| values.set(v),
    TagOption { value: "a".to_string(), "Tag A" TagRemoveButton {} }
}

Alert {
    AlertTitle { "Heads up" }
    AlertDescription { "This is an important message." }
}

Empty {
    EmptyHeader {
        EmptyTitle { "No results" }
        EmptyDescription { "Try a different search." }
    }
}

KbdGroup {
    Kbd { "Ctrl" }
    Kbd { "K" }
}

Breadcrumb {
    BreadcrumbList {
        BreadcrumbItem { BreadcrumbLink { href: "/", "Home" } }
        BreadcrumbSeparator {}
        BreadcrumbItem { BreadcrumbPage { "Current" } }
    }
}

Table {
    TableHeader { TableRow { TableHead { "Name" } } }
    TableBody { TableRow { TableCell { "adico" } } }
}

ButtonGroup {
    Button { variant: ButtonVariant::Outline, "Left" }
    ButtonGroupSeparator {}
    Button { variant: ButtonVariant::Outline, "Right" }
}

InputGroup {
    InputGroupAddon { InputGroupText { "$" } }
    InputGroupInput { placeholder: "0.00" }
}

NativeSelect { value: value(), oninput: move |event| value.set(event.value()),
    NativeSelectOption { value: "apple", "Apple" }
    NativeSelectOption { value: "banana", "Banana" }
}
